 $('#profile-help').onclick=()=>{closeProfile();const m=$('#modal');m.innerHTML='<h2>Sprocket CRM</h2><p>A configurable, open-source CRM.</p><p>This local version supports records, pipelines, activity logs and optional SSO.</p><div class="actions"><button id="about-close">Close</button></div>';$('#about-close').onclick=()=>m.close();m.showModal()};
 if($('#sign-out'))$('#sign-out').onclick=async()=>{await fetch('/auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});location.href='/login'};
 $('#global-search').onkeydown=e=>{if(e.key==='Enter'){const q=e.target.value.toLowerCase().trim();if(!q)return;$('#content').innerHTML=`<h1>Search results</h1><p>Across all record types</p>${state.records.filter(r=>JSON.stringify(r).toLowerCase().includes(q)).map(r=>`<div class="report-row"><button data-result="${esc(r.id)}">${esc(r.name)}</button><span>${esc(type(r.kind)?.name)}</span></div>`).join('')||'<div class="empty">No matching records.</div>'}`;document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>recordModal(state.records.find(r=>r.id===b.dataset.result)))}};
 $('#quick-create').onclick=()=>createMenu();
